from dental_release.paths import expand as _release_expand
from common_r3 import *
import collections, subprocess

def run():
    result = read(ROOT / 'results.json')
    summary = {tag: rr['summary'] for (tag, rr) in result['rounds'].items()}
    attempts = []
    for tag in ['A', 'B', 'C']:
        pr = read(ROOT / f'PREREG_{tag}.json')
        rr = result['rounds'][tag]
        attempts.append(dict(round=tag, parent=['PROOF_LANE_FULL_CROWN_R2', 'PROOF_LANE_FULL_CROWN_R3/A' if tag != 'A' else _release_expand('FULL_CROWN')], claim_type='capability', changed_operation=pr['changed_operation'], prereg_sha256=sha(ROOT / f'PREREG_{tag}.json'), prediction_sha256=sha(ROOT / f'FROZEN_PREDICTIONS_{tag}.json'), summary=rr['summary'], dropout=rr['dropout'], external_referent=REFERENT))
    dump(ROOT / 'ATTEMPTS.json', dict(attempts=attempts, parent_capability='Full anatomy AND function on actual preparation remains open', prior_oom='Resource interruption, not scientific falsification'))
    peaks = [result['cost']['A_resume']['peak_rss_MiB'], result['cost']['B_generate']['peak_rss_MiB'], result['cost']['C_generate']['peak_rss_MiB']] + [r['peak_worker_rss_MiB'] for r in result['rounds'].values()] + [read(ROOT / 'raw/SCORER_CONTROLS.json')['peak_rss_MiB']]
    if (ROOT / 'raw/DEMO_RECHECK.json').exists():
        peaks += [x['peak_rss_MiB'] for x in read(ROOT / 'raw/DEMO_RECHECK.json')['rows'] if x['peak_rss_MiB'] is not None]
    peak = max(peaks)
    assert peak < 4096
    result['verification'] = read(ROOT / 'raw/DEMO_RECHECK.json')
    result['selected_generator_replay'] = read(ROOT / 'raw/GENERATOR_REPLAY.json')
    result['resource_summary'] = dict(maximum_observed_worker_rss_MiB=peak, demo_parent_rss_MiB=result['verification']['parent_peak_rss_MiB'], sum_of_worker_and_demo_parent_maxima_MiB=peak + result['verification']['parent_peak_rss_MiB'], scope='Per-process maxima; sum is a conservative combination of these observed maxima, not a cgroup memory trace')
    dump(ROOT / 'results.json', result)
    with (ROOT / 'COMMANDS.md').open('a') as f:
        f.write(f'\n- Final authoritative maximum observed worker RSS: {peak:.3f} MiB, from internal resource.getrusage plus direct scorer /usr/bin/time. All numeric workers hard-capped at3584MiB address space. Parent process costs are reported separately. Original OOM peak UNKNOWN.\n')
    notes = ['# R3b handoff: full crown parent objective remains open', '', 'Three preregistered constructions were executed on the unchanged18 sites. Original acquisition, cohort, A protocol and A code hashes remain unchanged. Original two first-molar exports were preserved. Memory repair bounds candidate lists and isolates one tooth/method per process; maximum observed numeric-worker RSS ' + f'{peak:.3f} MiB.', '', json.dumps(clean(summary), indent=2), '', 'All raw failed gates: rounds/A.json, rounds/B.json, rounds/C.json. Do not promote a contact-only or native-empty pass to full crown success. Lab STL/3MF selections and all rejection labels: FROZEN_LAB_PREDICTIONS.json. No real fabrication or measurement was performed.', '', 'C follows a different obstacle from A/B: clipping endpoints changes PL band edge crossings. It keeps raw source values on crossing-face vertices while reusing the identical B generator. raw/CLIPPING_SUFFICIENCY.json separates the information counterexample from external scan evidence. The same source provides the prescribed contact field: this is retrospective construction, not independent contact prediction.', '', 'Next construction: preserve C contact-bearing boundary nodes but replace the vertical axial skirt and assumed planar finish line by a closed expert-annotated3D preparation boundary and a patient-disjoint full-surface prior. A generator needs explicit supported axial regions, actual preparation geometry and calibrated antagonist pose/load. Three of six native premolars fail the existing penetration constraint even against themselves; retain these observations and test registration/segmentation rather than relaxing the gate. Existing R1/R2 contralateral, affine, Poisson and co-designed cavity attempts must not be repeated unchanged.', '', 'More immediate executable diagnostic: first supply the C crossing-face endpoint data to the frozen A localized deformation and its scalar control, retaining all18 sites and thresholds; reuse unchanged-input cases. Then use the same C node-preserving operator with the inherited exterior below a frozen transition ring, and a constrained annular triangulation above it, leaving contact nodes fixed. Compare axial regional p95 and proximal patches separately. This remains a virtual-preparation experiment until an actual closed boundary is acquired; do not call planar skirt agreement measured fit.', '', _release_expand('One command: ./run_all.sh. It re-scores all frozen outputs and exercises negative controls. It actually regenerates the three selected crowns in fresh isolated outputs and checks exact geometry parity; it does not claim a second full-cohort generation. Exact initial generator argv and code/input hashes are recorded. Own arrays and exports are in @DENTAL_WORK_ROOT@/PROOF_LANE_FULL_CROWN_R3. No canonical graphs or other checkouts changed.'), '', 'Graph binds a review target only; missing numerical coverage is the explicit contact-edge-preserving full-crown construction proposed in GRAPH_COVERAGE_PROPOSAL.json. Review remains PENDING_INDEPENDENT_REVIEW; source/roundoff/clinical uncertainty remains unresolved.']
    (ROOT / 'HANDOFF.md').write_text('\n'.join(notes) + '\n')
    for tag in ['A', 'B', 'C']:
        p = ROOT / 'history' / f'HANDOFF_{tag}.md'
        p.write_text(p.read_text() + '\nNext executed construction: ' + ('B explicit exterior preservation' if tag == 'A' else 'C source gap endpoints on crossing faces' if tag == 'B' else 'see final HANDOFF.md for axial-surface/actual-preparation continuation') + '\n')
    dump(ROOT / 'GRAPH_COVERAGE_PROPOSAL.json', dict(status='PROPOSAL_ONLY', parent_target='DENT-VAL-BASELINE-COMPARISON', missing_coverage='Crown generator as receiver of measured per-point gap and threshold-crossing information while retaining full anatomy and actual preparation constraints', proposed_quantity='Source PL contact-band crossings -> explicit outer boundary mesh', resolution='PER_POINT', time_scale='SIMULTANEOUS', prerequisites=['registered calibrated gap', 'verified source tooth/axial support', 'actual closed preparation boundary'], scope='retrospective digital construction; no scientific admission'))
    subprocess.run([PYTHON, str(ROOT / 'code/command_manifest.py')], check=True)
    delivery = [ROOT / n for n in ['README_DEMO.md', 'RESULTS.md', 'HANDOFF.md', 'SOURCE_SELECTION.md', 'CONTACT_CROSSING_ARGUMENT.md', 'run_all.sh']] + list((ROOT / 'figures').glob('*'))
    payload = dict(delivery_artifacts={str(p.relative_to(ROOT)): sha(p) for p in delivery if p.is_file()}, results=result, attempts=read(ROOT / 'ATTEMPTS.json'), demo_recheck=read(ROOT / 'raw/DEMO_RECHECK.json'), selected_generator_replay=read(ROOT / 'raw/GENERATOR_REPLAY.json'), code={str(p.relative_to(ROOT)): sha(p) for p in (ROOT / 'code').glob('*.py')}, artifacts={p.name: sha(p) for p in ROOT.glob('*.json') if p.name not in ['CURRENT_WORK_STATE.json', 'REVIEW_SNAPSHOT.json', 'GRAPH_FEEDBACK.json']}, maximum_worker_rss_MiB=peak, scope='producer output pending independent review; physical measurement not run')
    if not (ROOT / 'REVIEW_SNAPSHOT.json').exists():
        freeze(ROOT / 'REVIEW_SNAPSHOT.json', payload)
    dispatch = read(BASE.parent / 'tasks/graph_runs/PROOF_LANE-full-crown-r3/DISPATCH.json')
    feedback = dict(target_id='DENT-VAL-BASELINE-COMPARISON', result_file='results/PROOF_LANE_FULL_CROWN_R3/REVIEW_SNAPSHOT.json', sha256=sha(ROOT / 'REVIEW_SNAPSHOT.json'), review_state='PENDING_INDEPENDENT_REVIEW', source_generation=dispatch['packet']['result_binding_template']['source_generation'], claim_type='capability', measured_quantity='Bidirectional sampled source p95, spatial band pattern/location/interference, wall and closed shell; per-point gap information preservation', units='mm,mm2,counts', uncertainty=result['uncertainty'], population_regime='18 fixed retrospective sites; four test and two auxiliary cases per tooth type; no patient-disjoint generalization claim', preregistered_gate='Anatomy0.35mm and unchanged GenCADv6 contact; wall0.5mm, planar margin0.025mm, proximal0.05..8mm2; joint criterion retained', baseline='R2 no measured sheet plus actually executed A scalar and spatial controls; B/C same operator with changed crossing information', outcome=json.dumps(clean(summary), separators=(',', ':')), negative_result=not any((r.get('anatomy_pass') and r.get('functional_pass_sampled') for rr in result['rounds'].values() for r in rr['rows'])), scientific_admission=False, external_referent=REFERENT, coverage='Existing review target only; numerical operation proposed separately', round_tag='PROOF_LANE-full-crown-r3b')
    dump(ROOT / 'GRAPH_FEEDBACK.json', feedback)
    dump(ROOT / 'CURRENT_WORK_STATE.json', dict(lane='PROOF_LANE-full-crown-r3b', claim_type='capability', phase='ROUNDS_A_B_C_COMPLETE_PARENT_OPEN', latest_gate=summary, next_operation='Independent review; then boundary-preserving axial graft with actual preparation/support annotations as specified in HANDOFF.md', maximum_worker_rss_MiB=peak, updated_utc=now(), review_state='PENDING_INDEPENDENT_REVIEW'))
    print('SEALED', peak)
if __name__ == '__main__':
    run()
